  str_season_s4_mission_desc_8004001 = "—",
  str_season_s4_mission_desc_8004002 = "—",
  str_season_s4_mission_desc_8004003 = "Arrie interactúa por primera vez con la tienda objetivo y negocia con el jefe bajo el pretexto de buscar una reliquia perdida.",
  str_season_s4_mission_desc_8004004 = "Arrie interactúa por primera vez con la tienda objetivo y negocia con el jefe bajo el pretexto de buscar una reliquia perdida.",
  str_season_s4_mission_desc_8004005 = "Arrie y el artesano tienen un plan. Seguirán encontrándose con el dueño de la tienda durante el día, y Arrie se escabullirá por la noche para confirmar si están diciendo la verdad.",
  str_season_s4_mission_desc_8004006 = "Arrie y el artesano tienen un plan. Seguirán encontrándose con el dueño de la tienda durante el día, y Arrie se escabullirá por la noche para confirmar si están diciendo la verdad.",
  str_season_s4_mission_desc_8004007 = "Por la noche, Arrie se cuela en la casa de un coleccionista y encuentra una existencia extremadamente ominosa en su interior...",
  str_season_s4_mission_desc_8004008 = "Por la noche, Arrie se cuela en la casa de un coleccionista y encuentra una existencia extremadamente ominosa en su interior...",
  str_season_s4_mission_desc_8004009 = "El jefe del gremio admite que habían manejado algunas antigüedades de Longzhou de origen desconocido, pero nunca enviarían a sus asociados a saquear el almacén de otra persona a punta de espada, y dirigió la sospecha hacia Arrie...",
  str_season_s4_mission_desc_8004010 = "El jefe del gremio admite que habían manejado algunas antigüedades de Longzhou de origen desconocido, pero nunca enviarían a sus asociados a saquear el almacén de otra persona a punta de espada, y dirigió la sospecha hacia Arrie...",
  str_season_s4_mission_desc_8004011 = "En la calle, una adivina que ha montado un puesto allí está contando una leyenda sobre una espadachina maldita del pasado...",
  str_season_s4_mission_desc_8004012 = "En la calle, una adivina que ha montado un puesto allí está contando una leyenda sobre una espadachina maldita del pasado...",
  str_season_s4_mission_desc_8004013 = "Arrie y el artesano continúan su investigación. Esta vez, visitarán a un informante en una botica...",
  str_season_s4_mission_desc_8004014 = "Arrie y el artesano continúan su investigación. Esta vez, visitarán a un informante en una botica...",
  str_season_s4_mission_desc_8004015 = "Las pistas llevan a Arrie a los muelles para alquilar un bote...",
  str_season_s4_mission_desc_8004016 = "Las pistas llevan a Arrie a los muelles para alquilar un bote...",
  str_season_s4_mission_desc_8004017 = "Como ella esperaba, Arrie comenzó a sentir el aura ominosa de nuevo después de entrar en la galería. La verdadera identidad de la cosa que emana esta aura es...",
  str_season_s4_mission_desc_8004018 = "Como esperaba, Arrie comenzó a sentir el aura ominosa nuevamente después de entrar en la galería. La verdadera identidad de la cosa que emana esta aura es...",
  str_season_s4_mission_desc_8004019 = "Arrie se enfrenta al Malvado Espadachín en una feroz batalla en la galera. Sin embargo, su oponente es increíblemente poderoso, y ella lucha desesperadamente por una oportunidad para ganar.",
  str_season_s4_mission_desc_8004020 = "Arrie se enfrenta al Malvado Espadachín en una feroz batalla en la galera. Sin embargo, su oponente es increíblemente poderoso, y ella lucha desesperadamente por una oportunidad para ganar.",
  str_season_s4_mission_desc_8004021 = "Herida, Arrie evita a la multitud y camina sola. El artesano la encuentra y le dice que los gremios han acordado ayudarlos. Sin embargo, Arrie dice que quizás no pueda seguir haciendo esta misión.",
  str_season_s4_mission_desc_8004022 = "Herida, Arrie evita a la multitud y camina sola. El artesano la encuentra y le dice que los gremios han acordado ayudarlos. Sin embargo, Arrie dice que quizás no pueda seguir haciendo esta misión.",
  str_season_s4_mission_desc_8004023 = "Por la noche, los dos persiguen al Malvado Espadachín y lo obligan a subir a la torre de la puerta.",
  str_season_s4_mission_desc_8004024 = "Por la noche, los dos persiguen al Malvado Espadachín y lo obligan a subir a la torre de la puerta.",
  str_season_s4_mission_desc_8004025 = "Arrie y el Malvado Espadachín luchan otra intensa batalla en la cima de la torre de la puerta. Arrie inmoviliza al Malvado Espadachín con un gancho y asesta el golpe decisivo bajo la luna.",
  str_season_s4_mission_desc_8004026 = "Arrie y el Malvado Espadachín luchan otra intensa batalla en la cima de la torre de la puerta. Arrie inmoviliza al Malvado Espadachín con un gancho y asesta el golpe decisivo bajo la luna.",
  str_season_s4_mission_desc_8004027 = "Arrie abandona la torre de la puerta y continúa buscando a Vilanor, que ha volado lejos de la escena. Ella puede sentir sentimientos de odio intenso, dolor y pánico...",
  str_season_s4_mission_desc_8004028 = "Arrie abandona la torre de la puerta y continúa buscando a Vilanor, que ha volado lejos de la escena. Ella puede sentir sentimientos de odio intenso, dolor y pánico...",
  str_season_s4_mission_desc_8004029 = "Persiguiendo a Vilanor, la espadachina lucha todo el camino mientras se mueve por las calles bajo toque de queda. Finalmente, llega al lugar donde Vilanor despertó...",
  str_season_s4_mission_desc_8004030 = "Persiguiendo a Vilanor, la espadachina lucha todo el camino mientras se mueve por las calles bajo toque de queda. Finalmente, llega al lugar donde Vilanor despertó...",
  str_season_s4_mission_desc_8004031 = "Incluso ahora, aún anhela regresar a Longzhou, su ciudad natal, en un barco y encontrar el significado de su existencia.",
  str_season_s4_mission_desc_8004032 = "Incluso ahora, aún anhela regresar a Longzhou, su ciudad natal, en un barco y encontrar el significado de su existencia.",
  str_season_s4_mission_desc_8004101 = "Fundamentos de la esgrima: Forma de la espada",
  str_season_s4_mission_desc_8004102 = "Fundamentos de la esgrima: Forma de la espada",
  str_season_s4_mission_desc_8004103 = "Principios de Esgrima: Principios de la Espada",
  str_season_s4_mission_desc_8004104 = "Principios de Esgrima: Principios de la Espada",
  str_season_s4_mission_desc_8004105 = "Movimientos de esgrima: Movimiento de espada",
  str_season_s4_mission_desc_8004106 = "Movimientos de esgrima: Movimiento de espada",
  str_season_s4_mission_desc_8004107 = "Extensión de esgrima: Energía de espada",
  str_season_s4_mission_desc_8004108 = "Extensión de esgrima: Energía de espada",
  str_season_s4_mission_desc_8004109 = "Logros de esgrima: Intención de espada",
  str_season_s4_mission_desc_8004110 = "Logros de esgrima: Intención de espada",
  str_season_s4_mission_desc_8004111 = "Fusión de esgrima: Unidad de espada",
  str_season_s4_mission_desc_8004112 = "Fusión de esgrima: Unidad de espada",
  str_season_s4_task_list_mode_title = "Aviso de cambio de modo",
  str_season_s4_task_list_mode_msg = "Esta misión requiere cambiar al Modo Exploración. ¿Continuar ahora?",
  str_season_s4_unlock_desc_20301 = "Obtenido después de leer la historia de ST1 - Razón en Canción de Espada Bajo un Dosel de Sueños.",
  str_season_s4_unlock_desc_20302 = "Obtenido después de leer la secuela de N15 - Corazón de Espada en Canción de Espada Bajo un Dosel de Sueños.",
  str_season_s4_unlock_desc_20303 = "Obtenido después de leer la precuela de N5 - Maldición en Sword Song Under a Canopy of Dreams.",
  str_season_s4_unlock_desc_20304 = "Obtenido después de leer la secuela de N15 - Corazón de Espada en Canción de Espada Bajo un Dosel de Sueños.",
  str_season_s4_unlock_desc_20305 = "Obtenido después de leer la precuela de N9 - Expuesto en Sword Song Under a Canopy of Dreams.",
  str_season_s4_unlock_desc_20306 = "Obtenido después de leer la secuela de N9 - Expuesto en Sword Song Under a Canopy of Dreams.",
  str_season_s4_title_saiji_20301 = "Temprano Dawn Yo",
  str_season_s4_title_saiji_20302 = "Temprano Dawn II",
  str_season_s4_title_saiji_20303 = "Espadachina Legendario I",
  str_season_s4_title_saiji_20304 = "Espadachina Legendaria II",
  str_season_s4_title_saiji_20305 = "Espada Sombras Sobre las Olas I",
  str_season_s4_title_saiji_20306 = "Sombras de Espada Sobre las Olas II",
  str_season_s4_saiji_info_20301 = "La tenue luz del amanecer brilla en las calles de la Bahía de las Dos Paviliones donde los habitantes de la ciudad aún duermen profundamente, pero los pájaros, flores y mariposas de la calle ya han comenzado a dar la bienvenida a este nuevo amanecer. ¿Podrá Arrie también dar la bienvenida a su propio amanecer?",
  str_season_s4_saiji_info_20302 = "Después de completar la misión, la espadachina se apoya felizmente contra la barandilla con su amada espada mágica, disfrutando de una calidez y comodidad que nunca había experimentado mientras huía de la oscuridad en el pasado.",
  str_season_s4_saiji_info_20303 = "Hace mucho, mucho tiempo, había una débil y maldita espadachina que empuñaba una gran espada. Inmutable ante el dinero o la fama, la espadachina viajó a lo largo del Río Dorado, matando a todas las criaturas malditas del mundo solo para salvarse a sí misma.",
  str_season_s4_saiji_info_20304 = "Así dijo la adivina: \"Trata tu espada como a una persona, porque tu espada también tiene un corazón. En los sueños, las flores pueden brotar de las espinas y las espadas pueden hablar. La espada habla los pensamientos de las personas. ¡No olvides lo que escuchaste en tus sueños!\"",
  str_season_s4_saiji_info_20305 = "En la galera, Arrie solo podía bloquear pasivamente los poderosos ataques del Espadachín Malvado. En esta situación desventajosa, pensó cuidadosamente en contramedidas para crear una oportunidad para revertir la situación.",
  str_season_s4_saiji_info_20306 = "La ropa de Arrie se rasgó mientras luchaba contra el Espadachín Malvado en el barco, revelando las espinas en su cuerpo. En ese momento, comenzó a escuchar los comentarios impulsados por el miedo de los espectadores sobre la espada mágica y Vilanor, y empezó a ponerse tímida y nerviosa.",
  str_season_s4_mail_gm_season = "Puerta de Sueños",
  str_season_s4_mail_title_season = "Tokens restantes en el sueño",
  str_season_s4_mail_detail_season_1 = "Los Pasadores de Wisteria no utilizados de Dream: Sword Song Under a Canopy of Dreams se han convertido en Fragmentos de Sueño, que se pueden intercambiar por trajes y materiales de sueños pasados en Tienda - Canjear - Paisajes Auténticos de Sueños. Las Antiguas Monedas de Cobre no utilizadas se han cambiado por Nightium a una cierta tasa.\n\n{1} ×{2} se han cambiado por {3} ×{4}.",
  str_season_s4_mail_detail_season_2 = "Los Horquillas de Glicinia no utilizadas de Sueño: Canción de Espada Bajo un Dosel de Sueños se han convertido en Fragmentos de Sueño, que se pueden intercambiar por trajes y materiales de sueños pasados en Tienda - Canjear - Paisajes Auténticos de Sueños. Las Antiguas Monedas de Cobre no utilizadas se han cambiado por Nightium a una cierta tasa.\n\n{1} ×{2} se han cambiado por {5} ×{6}.\n{3} ×{4} se han cambiado por {7} ×{8}.",
  str_season_s4_buff_level_info_1 = "Genera <color=#9f5138>4</color> mosaicos cromáticos al azar en el campo cada ronda.\nAumenta el daño de la habilidad activa de los Aurorianos del Bosque en <color=#9f5138>100%</color>.\nNo puede entrar en Aurora Time.",
  str_season_s4_buff_level_info_2 = "Genera <color=#9f5138>6</color> mosaicos cromáticos al azar en el campo cada ronda.\nAumenta el daño de la habilidad activa de los aurorianos del bosque en un <color=#9f5138>120%</color>.\nNo puede entrar en Aurora Time.",
  str_season_s4_buff_level_info_3 = "Genera <color=#9f5138>6</color> fichas cromáticas al azar en el campo cada ronda.\nEl daño del Combo en Cadena y el ataque normal de los Aurorians Francotiradores se incrementará en un <color=#9f5138>20%</color>.\nAumenta el daño de la habilidad activa de los Aurorians de bosque en un <color=#9f5138>140%</color>.\nAl comienzo de la 7ª ronda, reduce el tiempo de recarga de la habilidad activa de los aliados en <color=#9f5138>1 ronda</color>.\nNo puede entrar en la Hora de Aurora.",
  str_season_s4_buff_level_info_4 = "Genera <color=#9f5138>8</color> fichas cromáticas al azar en el campo cada ronda.\nEl daño del Combo en Cadena y el ataque normal de los Aurorians Francotiradores se incrementará en un <color=#9f5138>40%</color>.\nAumenta el daño de la habilidad activa de los Aurorians de bosque en un <color=#9f5138>160%</color>.\nAl comienzo de la 7ª ronda, reduce el tiempo de recarga de la habilidad activa para los aliados en <color=#9f5138>1 ronda</color>.\nNo puede entrar en la Hora de Aurora.",
  str_season_s4_buff_level_info_5 = "Genera <color=#9f5138>10</color> fichas cromáticas aleatoriamente en el campo cada ronda.\nEl daño del Combo en Cadena y el ataque normal de los Aurorians Francotiradores se incrementará en un <color=#9f5138>60%</color>.\nAumenta el daño de la habilidad activa de los Aurorians de bosque en un <color=#9f5138>180%</color>.\nAl comienzo de la 7ª ronda, reduce el tiempo de recarga de la habilidad activa para los aliados en <color=#9f5138>1 ronda</color>.\nNo puede entrar en el Tiempo Aurora.",
